def solve(inputs: dict) -> float:
    n = inputs['n']
    k = inputs['k']

    # Josephus problem: n people in circle, eliminate every k-th
    people = list(range(1, n + 1))
    idx = 0

    while len(people) > 1:
        idx = (idx + k - 1) % len(people)
        people.pop(idx)

    return float(people[0])

